INSERT IGNORE INTO `newstart_knowledge_items`
(`knowledge_id`, `source_type`, `category`, `title`, `summary`, `content`, `authority`,
`tags`, `source_url`, `source_date`, `effective_from`, `effective_to`,
`version`, `status`, `confidence`, `related_case_ids`, `related_rule_ids`,
`created_by`, `updated_by`, `created_at`, `updated_at`, `dedup_key`)
VALUES (1583, 'OFFICIAL_CURRENT', '재산은닉·사후검증', '[연합뉴스 2026-10-15] 재산 숨기고 10억 빚 감면…새출발기금 재산은닉 16명 적발', '연합뉴스 2026-10-15 보도(캠코 자료, 국회 정무위 박성훈 의원실) — 새출발기금 시행 후 2026년 8월까지 재산은닉 확인으로 약정취소된 차주 16명, 채무원금 총 16억5,200만원, 원금감면액 10억5,500만원. 은닉 재산은 부동산·분양권·임차보증금·토지보상금 등. 2026년 8월 신용정보법 개정으로 증여·가상자산·비상장주식 재산정보 확인 기반 마련.', '## 출처 구분\n- 언론 보도: 연합뉴스 2026-10-15 (배영경 기자), 입력 05:53·수정 08:06\n- 근거 자료: 한국자산관리공사(캠코)가 국회 정무위원회 박성훈 의원실에 제출한 자료\n- 원문: https://n.news.naver.com/article/001/0016377731?sid=101\n- 이 항목은 기사 전문이 아니라 수집 요약본이다. 원문은 URL 참조.\n\n## 보도 내용\n- 새출발기금 시행 이후 2026년 8월까지, 재산을 숨긴 사실이 확인돼 채무조정 약정이 취소된 차주 16명.\n- 이들의 당초 채무원금 총 16억5,200만원, 원금감면액 10억5,500만원.\n- 은닉한 재산은 부동산뿐 아니라 분양권·임차보증금·토지보상금 등 다양. 일부는 4억~7억원대 상당의 부동산을 소유하고도 숨긴 채 채무조정을 받았다.\n- 캠코는 16명 전원 약정취소 완료, 현재 가압류 등 재산보전 조치와 강제집행을 위한 법적 절차 진행 중.\n- 그동안 새출발기금은 관계 기관에서 확보 가능한 일부 재산정보와 차주 신고 내역을 대조하는 방식으로 심사. 2026년 8월 신용정보법 개정으로 증여·가상자산·비상장주식 등 기존에 확인하기 어려웠던 재산정보까지 확보할 수 있는 제도적 기반 마련.\n\n## 다룰 때 주의\n- 보도 수치(16명·16억5,200만원·10억5,500만원)는 국회 제출 자료 기준이며, 공식 규정 문구가 아니다. 상담에서는 \'재산은닉이 확인되면 약정취소·가압류까지 간 사례가 있다\'는 수준으로만 쓰고, 개별 건의 적용 여부는 담당자 확인으로 넘긴다.\n- 이 항목만으로 특정 회원의 재산은닉 여부를 단정하지 않는다.', '연합뉴스 보도(2026-10-15, 배영경 기자) — 캠코 제출 자료(국회 정무위 박성훈 의원실)', '재산은닉,약정취소,가압류,사후검증,신용정보법,캠코,보도,date=2026-10-15', 'https://n.news.naver.com/article/001/0016377731?sid=101', '2026-10-15', NULL, NULL, 1, 'ACTIVE', 'medium', NULL, NULL, 'lib-import-20261003', 'lib-import-20261003', NOW(6), NOW(6), 'LIB20261003:KI:1583');
